KB = [
 ("Tráng phim đen trắng gồm những bước nào?","Các bước chính: developer, stop bath, fixer, rửa nước, tráng chất chống vệt rồi treo sấy. Nhiệt độ thường giữ khoảng 20 độ C và canh thời gian đúng theo loại phim và developer."),
 ("Tráng phim màu C-41 cần lưu ý gì?","C-41 đòi hỏi nhiệt độ rất ổn định khoảng 38 độ C, gồm các bước developer màu, blix và rửa. Sai nhiệt độ dễ làm lệch màu, nên nên dùng bể ổn nhiệt."),
 ("Đèn an toàn trong phòng tối dùng màu gì?","Giấy ảnh đen trắng thường dùng đèn an toàn màu đỏ hoặc cam. Phim thì phải xử lý trong bóng tối hoàn toàn, không dùng đèn an toàn."),
 ("Máy phóng ảnh (enlarger) dùng để làm gì?","Máy phóng chiếu hình ảnh từ phim âm bản lên giấy ảnh để in phóng to. Có thể chỉnh độ cao, lấy nét và thời gian phơi sáng."),
 ("Làm sao chọn thời gian phơi khi in ảnh?","Dùng test strip: phơi từng đoạn giấy với thời gian khác nhau rồi chọn đoạn có độ đen và chi tiết vùng sáng hợp lý nhất."),
 ("Phim ISO 400 khác ISO 100 thế nào?","ISO 400 nhạy sáng hơn nên chụp trong điều kiện thiếu sáng tốt hơn nhưng hạt phim thô hơn. ISO 100 hạt mịn, cần nhiều ánh sáng hơn."),
 ("Nên chọn phim đen trắng nào cho người mới?","Người mới thường bắt đầu với Ilford HP5 Plus 400 hoặc Kodak Tri-X 400 vì dễ tính, độ dung sai phơi sáng rộng."),
 ("Phim âm bản màu khác phim slide thế nào?","Phim âm bản cho ra hình ngược màu và cần in hoặc quét, độ dung sai phơi sáng rộng. Phim slide cho ra hình dương bản trực tiếp nhưng khó phơi chính xác hơn."),
 ("Cách quét phim để có chất lượng tốt?","Làm sạch phim, dùng độ phân giải 3200 đến 4000 dpi, quét ở chế độ 16-bit rồi chỉnh sửa sau. Tránh bật các bộ lọc tự động mạnh."),
 ("Làm sao bảo quản phim chưa chụp?","Để nơi mát và khô, tốt nhất trong tủ lạnh nếu để lâu, ngăn tia X và nhiệt độ cao. Để phim về nhiệt độ phòng trước khi dùng."),
 ("Phim đã chụp nên giữ bao lâu trước khi tráng?","Nên tráng sớm. Nếu phải đợi, giữ nơi mát và khô, phim để lâu có thể bị mờ hoặc lệch màu, nhất là khi nóng ẩm."),
 ("Hóa chất tráng phim có độc không và xử lý thế nào?","Một số hóa chất gây kích ứng da và mắt. Cần đeo găng, kính, làm việc nơi thông gió, không đổ trực tiếp ra cống mà thu gom và xử lý đúng quy định."),
 ("Cách pha hóa chất developer đúng cách?","Pha đúng tỷ lệ nhà sản xuất, dùng nước sạch ở nhiệt độ quy định, khuấy đều và ghi ngày pha. Developer pha loãng thường dùng một lần."),
 ("Stop bath dùng để làm gì?","Stop bath là dung dịch axit nhẹ dừng phản ứng của developer ngay lập tức, bảo vệ fixer và giúp kết quả đồng đều. Có thể thay bằng nước rửa nếu cần."),
 ("Fixer làm gì và cố định trong bao lâu?","Fixer hòa tan bạc halogen chưa phơi sáng để ảnh không nhạy sáng nữa. Thời gian thường từ 3 đến 8 phút tùy loại phim và nồng độ."),
 ("Giấy ảnh RC và giấy fiber khác nhau thế nào?","Giấy RC phủ nhựa, xử lý và sấy nhanh. Giấy fiber thấm nước, rửa lâu hơn nhưng bền và đẹp hơn, thường dùng cho in triển lãm."),
 ("Dodge và burn là gì?","Dodge là che bớt ánh sáng để vùng đó sáng hơn, burn là cho thêm sáng để vùng đó tối hơn khi in phóng, giúp cân bằng độ tương phản cục bộ."),
 ("Máy ảnh phim cơ cho người mới nên chọn gì?","Các máy SLR cơ như Pentax K1000, Canon AE-1 hay Nikon FM2 bền, dễ sửa và có nhiều ống kính, hợp người mới học."),
 ("Cách đo sáng khi chụp phim?","Dùng máy đo sáng trong máy hoặc ứng dụng đo sáng. Với phim âm bản nên ưu tiên đo vùng tối và thà dư sáng hơn thiếu sáng."),
 ("Push và pull phim nghĩa là gì?","Push là phơi thiếu rồi tráng lâu hơn để tăng độ nhạy, pull là phơi dư và tráng ngắn hơn. Cả hai ảnh hưởng đến độ tương phản và hạt."),
 ("Ảnh phim bị xước hoặc bụi, xử lý sao?","Giữ phim sạch, dùng quạt thổi và vải không xơ. Khi quét có thể dùng chế độ loại bụi, hoặc làm sạch thủ công bằng phần mềm chỉnh ảnh."),
 ("Có thể phục chế ảnh cũ bằng cách nào?","Quét độ phân giải cao, sau đó loại bỏ vết xước, vết ố và phục hồi độ tương phản. Có thể dùng công cụ AI để hỗ trợ nhưng cần kiểm tra lại chi tiết."),
 ("Khi đặt phòng tối nên chuẩn bị gì?","Mang phim hoặc tờ ảnh âm bản, giấy ảnh nếu cần, găng tay và tạp dề. Hỏi trước phòng có sẵn hóa chất và thiết bị nào để khỏi mang thừa."),
 ("Nên thuê phòng tối bao lâu cho lần đầu?","Người mới nên thuê 3 đến 4 giờ để làm quen thiết bị và quy trình, có thể cần thêm thời gian cho thử test strip và rửa ảnh."),
 ("Chi phí in ảnh trong phòng tối gồm những khoản nào?","Gồm giá thuê phòng theo giờ, thuê thiết bị, hóa chất và giấy ảnh tiêu hao. Một số nơi bán gói trọn bộ có giá tốt hơn thuê lẻ."),
 ("Studio chụp phim cần ánh sáng thế nào?","Phim cần đủ sáng hơn máy số, nhất là phim ISO thấp. Đèn flash studio hoặc đèn liên tục cùng ánh sáng tự nhiên đều dùng được, nhớ đo sáng kỹ."),
 ("Chụp chân dung phim cần lưu ý gì?","Đo sáng trên da, dùng đèn mềm như softbox để da mịn, và chụp dư vài tấm vì phim không xem lại được ngay."),
 ("Làm sao hủy hoặc đổi lịch đặt phòng?","Mỗi nhà cung cấp có chính sách riêng, thường cho đổi hoặc hủy miễn phí trước một khoảng thời gian nhất định. Hãy xem phần chính sách trong trang chi tiết phòng."),
 ("Tham gia workshop nhiếp ảnh phim thế nào?","Xem mục workshop trong cộng đồng, đăng ký theo lịch do chuyên gia hoặc nhà cung cấp đăng. Số lượng chỗ thường có hạn nên nên đặt sớm."),
]
